CPU.write_state:
/Function(function(vec) {
      if (typeof vec.CPU > "u")
        vec.CPU = {};
      var internal_reg = ["PC"], value = 0;
      for (var i = 0;i < sim_p.states.BR.length; i++) {
        value = parseInt(get_value(sim_p.states.BR[i])) >>> 0;
        if (value != 0)
          vec.CPU["R" + i] = { type: "register", default_value: 0, id: "R" + i, op: "=", value: "0x" + value.toString(16) };
      }
      for (i = 0;i < internal_reg.length; i++) {
        value = parseInt(get_value(sim_p.states["REG_" + internal_reg[i]])) >>> 0;
        if (value != 0)
          vec.CPU[internal_reg[i]] = { type: "register", default_value: 0, id: internal_reg[i], op: "=", value: "0x" + value.toString(16) };
      }
      return vec;
    })/

CPU.read_state:
/Function(function(vec, check) {
      if (typeof vec.CPU > "u")
        vec.CPU = {};
      var key = check.id.toUpperCase().trim(), val = parseInt(check.value).toString(16);
      if (check.type.toUpperCase().trim() == "REGISTER") {
        vec.CPU[key] = { type: "register", default_value: 0, id: key, op: check.condition, value: "0x" + val };
        return !0;
      }
      return !1;
    })/

CPU.get_state:
/Function(function(reg) {
      var value = 0, r_reg = reg.toUpperCase().trim();
      if (typeof sim_p.states["REG_" + r_reg] < "u") {
        value = get_value(sim_p.states["REG_" + r_reg]) >>> 0;
        return "0x" + value.toString(16);
      }
      r_reg = r_reg.replace("R", "");
      var index = parseInt(r_reg);
      if (typeof sim_p.states.BR[index] < "u") {
        value = get_value(sim_p.states.BR[index]) >>> 0;
        return "0x" + value.toString(16);
      }
      return null;
    })/

CPU.get_value:
/Function(function(elto) {
      var r_ref = simhw_sim_state_getref(elto);
      if (typeof r_ref > "u")
        throw Error("unknown element named " + elto);
      return get_value(r_ref) >>> 0;
    })/

CPU.set_value:
/Function(function(elto, value) {
