      var verbal = "", address = "0x" + get_value(sim_p.states[s_expr[1]]).toString(16), dbvalue = get_value(sim_p.states[s_expr[2]]), bw = sim_p.signals[s_expr[3]].value, clk = get_value(sim_p.states[s_expr[4]]), bw_type = "word";
      if (bw == 1)
        bw_type = "byte";
      else if (bw == 2)
        bw_type = "half";
      var value = main_memory_getvalue(sim_p.internal_states.MP, address);
      if (typeof value > "u")
        value = 0;
      var verbose = get_cfg("verbal_verbose");
      if (verbose !== "math")
        verbal = "Try to write a " + bw_type + " to memory at address " + address + " with value " + value.toString(16) + ". ";
      verbal = "Memory[" + address + "] = 0x" + value.toString(16) + " (Write a " + bw_type + " to " + address + "). ";
      return verbal;
    })/

