IO_CHK_I.operation:
/Function(function(s_expr) {
      var clk = get_value(sim_p.states[s_expr[1]]);
      for (var i = sim_p.internal_states.io_int_factory.length - 1;i >= 0; i--) {
        if (get_var(sim_p.internal_states.io_int_factory[i].period) == 0)
          continue;
        if (get_var(sim_p.internal_states.io_int_factory[i].active) == !0) {
          set_value(sim_p.signals[s_expr[2]], 1);
          set_value(sim_p.states[s_expr[3]], i);
        }
        if (clk % get_var(sim_p.internal_states.io_int_factory[i].period) == 0) {
          if (Math.random() > get_var(sim_p.internal_states.io_int_factory[i].probability))
            continue;
          var acc = get_var(sim_p.internal_states.io_int_factory[i].accumulated);
          set_var(sim_p.internal_states.io_int_factory[i].accumulated, acc + 1);
          set_var(sim_p.internal_states.io_int_factory[i].active, !0);
          if (typeof sim_p.events.io[clk] > "u")
            sim_p.events.io[clk] = [];
          sim_p.events.io[clk].push(i);
          set_value(sim_p.signals[s_expr[2]], 1);
          set_value(sim_p.states[s_expr[3]], i);
        }
      }
    })/

INTA.operation:
/Function(function(s_expr) {
      var clk = get_value(sim_p.states[s_expr[1]]);
      if (typeof sim_p.events.io[clk] < "u") {
        set_value(sim_p.states[s_expr[4]], sim_p.events.io[clk][0]);
        return;
      }
      set_value(sim_p.signals[s_expr[2]], 0);
      set_value(sim_p.states[s_expr[5]], 0);
      for (var i = 0;i < sim_p.internal_states.io_int_factory.length; i++)
        if (get_var(sim_p.internal_states.io_int_factory[i].active)) {
          set_value(sim_p.signals[s_expr[2]], 0);
          set_value(sim_p.states[s_expr[5]], i);
          set_value(sim_p.states[s_expr[4]], i);
          if (typeof sim_p.events.io[clk] > "u")
            sim_p.events.io[clk] = [];
          sim_p.events.io[clk].push(i);
          set_var(sim_p.internal_states.io_int_factory[i].active, !1);
          break;
        }
    })/

IO_RESET.operation:
