L3D_RESET.operation:
/Function(function(s_expr) {
      sim_p.events.l3d = {};
      var n = sim_p.internal_states.l3d_state.length;
      for (var i = 0;i < n; i++)
        set_var(sim_p.internal_states.l3d_state[i].active, !1);
      n = Math.pow(sim_p.internal_states.l3d_dim, 3);
      var o = "0".repeat(n);
      sim_p.internal_states.l3d_frame = o;
      simcore_rest_call("L3D", "POST", "/", { frame: o });
    })/

L3D_SYNC.operation:
/Function(function(s_expr) {
      var l3dstates = sim_p.internal_states.l3d_state, o = "", p = 0, n = sim_p.internal_states.l3d_dim;
      for (var i = 0;i < n; i++)
        for (var j = 0;j < n; j++)
          for (var k = 0;k < n; k++) {
            p = k * Math.pow(sim_p.internal_states.l3d_dim, 2) + j * sim_p.internal_states.l3d_dim + i;
            if (get_var(l3dstates[p].active))
              o = o + "1";
            else
              o = o + "0";
          }
      if (sim_p.internal_states.l3d_frame != o) {
        sim_p.internal_states.l3d_frame = o;
        simcore_rest_call("L3D", "POST", "/", { frame: o });
      }
    })/

