LEDM_IOW.operation:
/Function(function(s_expr) {
      var bus_ab = get_value(sim_p.states[s_expr[1]]), bus_db = get_value(sim_p.states[s_expr[2]]);
      switch (bus_ab) {
        case LEDMSR_ID:
          set_value(sim_p.states[s_expr[3]], bus_db);
          break;
        case LEDMDR_ID:
          set_value(sim_p.states[s_expr[5]], bus_db);
          break;
        case LEDMCR_ID:
          set_value(sim_p.states[s_expr[4]], bus_db);
          break;
        default:
          break;
      }
      if (LEDMCR_ID == bus_ab) {
        var dr = get_value(sim_p.states[s_expr[5]]), sr = get_value(sim_p.states[s_expr[3]]);
        if (16 & bus_db) {
          var x = (dr & 4278190080) >>> 24, y = (dr & 16711680) >>> 16, s = dr & 255;
          set_value(sim_p.states[s_expr[3]], 1);
          if (x >= sim_p.internal_states.ledm_dim && y >= sim_p.internal_states.ledm_dim) {
            set_value(sim_p.states[s_expr[3]], -1);
            return;
          }
          var p = y * sim_p.internal_states.ledm_dim + x;
          set_var(sim_p.internal_states.ledm_state[p].color, s);
          sim_p.internal_states.ledm_sync = !1;
        }
        if (32 & bus_db) {
          set_value(sim_p.states[s_expr[3]], 1);
          var s = 0, neltos = sim_p.internal_states.ledm_neltos;
          for (var p = 0;p < neltos; p = p + 4) {
            s = simcore_native_get_value("MEMORY", dr + p);
            set_var(sim_p.internal_states.ledm_state[p + 0].color, (s & 255) >>> 0);
            set_var(sim_p.internal_states.ledm_state[p + 1].color, (s & 65280) >>> 8);
            set_var(sim_p.internal_states.ledm_state[p + 2].color, (s & 16711680) >>> 16);
            set_var(sim_p.internal_states.ledm_state[p + 3].color, (s & 4278190080) >>> 24);
          }
          sim_p.internal_states.ledm_sync = !1;
        }
        if (64 & bus_db) {
          set_value(sim_p.states[s_expr[3]], 1);
          var s = 0, c = "", neltos = sim_p.internal_states.ledm_colors.length;
          for (var p = 0;p < neltos; p++) {
            s = simcore_native_get_value("MEMORY", dr + p * 4);
            s = (s & 4294967040) >>> 8;
            s = s.toString(16);
            c = "#" + simcoreui_pack(s, 6);
            sim_p.internal_states.ledm_colors[p] = c;
          }
          neltos = sim_p.internal_states.ledm_neltos;
          for (var p = 0;p < neltos; p++) {
            s = get_var(sim_p.internal_states.ledm_state[p].color);
            set_var(sim_p.internal_states.ledm_state[p].color, ~s);
            set_var(sim_p.internal_states.ledm_state[p].color, s);
          }
          sim_p.internal_states.ledm_sync = !1;
        }
        if (128 & bus_db) {
          set_value(sim_p.states[s_expr[3]], 1);
          var nrows = sr;
          if (nrows > sim_p.internal_states.ledm_dim)
            nrows = sim_p.internal_states.ledm_dim;
          var neltos = nrows * sim_p.internal_states.ledm_dim, s = 0;
          for (var p = 0;p < neltos; p = p + 4) {
            s = simcore_native_get_value("MEMORY", dr + p);
            set_var(sim_p.internal_states.ledm_state[p + 0].color, (s & 255) >>> 0);
            set_var(sim_p.internal_states.ledm_state[p + 1].color, (s & 65280) >>> 8);
            set_var(sim_p.internal_states.ledm_state[p + 2].color, (s & 16711680) >>> 16);
            set_var(sim_p.internal_states.ledm_state[p + 3].color, (s & 4278190080) >>> 24);
          }
          sim_p.internal_states.ledm_sync = !1;
        }
      }
    })/

LEDM_IOW.verbal:
/Function(function(s_expr) {
      var verbal = "", bus_ab = get_value(sim_p.states[s_expr[1]]), bus_db = get_value(sim_p.states[s_expr[2]]);
      switch (bus_ab) {
        case LEDMSR_ID:
          verbal = "I/O device write at LEDMSR with value " + bus_db + ". ";
          break;
        case LEDMDR_ID:
          verbal = "I/O device write at LEDMCR with value " + bus_db + ". ";
          break;
        case LEDMCR_ID:
          var dr = get_value(sim_p.states[s_expr[5]]);
          if (16 & bus_db) {
            var x = (dr & 4278190080) >>> 24, y = (dr & 16711680) >>> 16, s = dr & 255;
            verbal = "I/O device write at LEDMCR with value " + bus_db + " (set pixel x:" + x + ", y:" + y + ", with color:" + s + "). ";
          }
          if (32 & bus_db)
            verbal = "";
          if (64 & bus_db)
            verbal = "I/O device write at LEDMCR with value " + bus_db + " (set color palette at:" + bus_db + "). ";
          if (128 & bus_db)
            verbal = "";
          break;
        default:
          break;
      }
      return verbal;
    })/

LEDM_RESET.operation:
/Function(function(s_expr) {
      sim_p.events.ledm = {};
      sim_p.internal_states.ledm_colors = colors_clone("");
      for (var i = 0;i < sim_p.internal_states.ledm_state.length; i++) {
        set_var(sim_p.internal_states.ledm_state[i].color, 1);
        set_var(sim_p.internal_states.ledm_state[i].color, 0);
      }
      var n = Math.pow(sim_p.internal_states.ledm_dim, 2), o = "0".repeat(n);
      sim_p.internal_states.ledm_frame = o;
      simcore_rest_call("LEDM", "POST", "/", { frame: o });
      sim_p.internal_states.ledm_sync = !1;
    })/

LEDM_SYNC.operation:
/Function(function(s_expr) {
      if (sim_p.internal_states.ledm_sync)
        return;
      var ledmstates = sim_p.internal_states.ledm_state, o = "", p = 0;
      for (var j = 0;j < sim_p.internal_states.ledm_dim; j++)
        for (var k = 0;k < sim_p.internal_states.ledm_dim; k++) {
          p = j * sim_p.internal_states.ledm_dim + k;
          o = o + get_var(ledmstates[p].color).toString(16);
        }
      if (sim_p.internal_states.ledm_frame != o) {
        sim_p.internal_states.ledm_frame = o;
        simcore_rest_call("LEDM", "POST", "/", { frame: o });
      }
      sim_p.internal_states.ledm_sync = !0;
    })/

SND_IOR.operation:
/Function(function(s_expr) {
      var bus_ab = get_value(sim_p.states[s_expr[1]]);
      if (bus_ab == SSR_ID) {
        var dsr = get_value(sim_p.states[s_expr[4]]);
        set_value(sim_p.states[s_expr[2]], dsr);
      }
      if (bus_ab == SDR1_ID) {
        var ddr = get_value(sim_p.states[s_expr[5]]);
        set_value(sim_p.states[s_expr[2]], ddr);
      }
      if (bus_ab == SDR2_ID) {
        var ddr = get_value(sim_p.states[s_expr[6]]);
        set_value(sim_p.states[s_expr[2]], ddr);
      }
      if (bus_ab == SDR3_ID) {
        var ddr = get_value(sim_p.states[s_expr[7]]);
        set_value(sim_p.states[s_expr[2]], ddr);
      }
    })/

SND_IOR.verbal:
/Function(function(s_expr) {
      var verbal = "", bus_ab = get_value(sim_p.states[s_expr[1]]);
      if (bus_ab == SDR1_ID) {
        var dsr = get_value(sim_p.states[s_expr[4]]);
        verbal = "Try to read into the sound the SSR value " + dsr + ". ";
      }
      if (bus_ab == SDR1_ID) {
        var ddr = get_value(sim_p.states[s_expr[5]]);
        verbal = "Try to read from the sound the SDR1 value " + ddr + ". ";
      }
      if (bus_ab == SDR2_ID) {
        var ddr = get_value(sim_p.states[s_expr[6]]);
        verbal = "Try to read from the sound the SDR2 value " + ddr + ". ";
      }
      if (bus_ab == SDR3_ID) {
        var ddr = get_value(sim_p.states[s_expr[7]]);
        verbal = "Try to read from the sound the SDR3 value " + ddr + ". ";
      }
      return verbal;
    })/

SND_IOW.operation:
/Function(function(s_expr) {
      var bus_ab = get_value(sim_p.states[s_expr[1]]);
      if (bus_ab != SDR1_ID && bus_ab != SDR2_ID && bus_ab != SDR3_ID)
        return;
      var bus_db = get_value(sim_p.states[s_expr[2]]), clk = get_value(sim_p.states[s_expr[3]]), ret_ok = 1;
      if (bus_ab == SDR1_ID) {
        set_value(sim_p.states[s_expr[5]], bus_db);
        if (typeof sim_p.events.sound[clk] > "u") {
          sim_p.events.sound[clk] = bus_db;
          if (bus_db == 2) {
            var sdr2 = get_value(sim_p.states[s_expr[6]]), n1 = simcore_sound_ascii2note(sdr2, 4), sdr3 = get_value(sim_p.states[s_expr[7]]), t1 = sdr3 & 255;
            t1 = t1 + "n";
            var n1t1 = n1 + "," + t1 + ";";
            sim_p.internal_states.sound_content += n1t1;
            var sound = get_sound_content();
            set_sound_content(sound + n1t1 + " ");
            ret_ok = simcore_sound_playNote(n1, t1);
          }
          if (bus_db == 1)
            ret_ok = simcore_sound_start();
          if (bus_db == 0)
            ret_ok = simcore_sound_stop();
        }
      }
      if (bus_ab == SDR2_ID)
        set_value(sim_p.states[s_expr[6]], bus_db);
      if (bus_ab == SDR3_ID)
        set_value(sim_p.states[s_expr[7]], bus_db);
      set_value(sim_p.states[s_expr[4]], ret_ok);
    })/

SND_IOW.verbal:
/Function(function(s_expr) {
      var verbal = "", bus_ab = get_value(sim_p.states[s_expr[1]]), bus_db = get_value(sim_p.states[s_expr[2]]), clk = get_value(sim_p.states[s_expr[3]]);
      if (bus_ab == SDR1_ID)
        verbal = "Try to write into the sound SDR1 the code " + bus_db + " at clock cycle " + clk + ". ";
      if (bus_ab == SDR2_ID)
        verbal = "Try to write into the sound SDR2 the code " + bus_db + " at clock cycle " + clk + ". ";
      if (bus_ab == SDR3_ID)
        verbal = "Try to write into the sound SDR3 the code " + bus_db + " at clock cycle " + clk + ". ";
      return verbal;
    })/
